        JISREM.CLEANUP_CASE_QUEUE
    SET
        status = 'VALIDATION_FAILED',
        message = v_validation_error
    WHERE
        cleanup_id = 'b61a0559-eabb-4dfc-95bb-fcf744e9b4bc'
        AND charge_id = 1085925;
   
    RETURN;
END IF;

END IF;

